pub fn get_element_check_property(arr: Vec<u64>, i: usize) -> u64 {
    // Preconditions from the problem statement.
    assert!(!arr.is_empty(), "array length must be positive");
    assert!(i > 0 && i < arr.len(), "index must satisfy 0 < i < len");

    // Global property: arr[k] == k + 2 for all valid k.
    // We can rely on it, but we also check it to match the problem statement.
    for (k, &v) in arr.iter().enumerate() {
        let expected = (k as u64) + 2;
        assert!(
            v == expected,
            "global property violated at k={k}: got {v}, expected {expected}"
        );
    }

    // Now the returned value equals both arr[i] and i + 2.
    let ret = arr[i];
    debug_assert_eq!(ret, (i as u64) + 2);
    ret
}